            "svg": "<svg viewBox=\"0 0 1100 1100\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" font-size=\"36\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">George Wythe 1726-1806</text><text x=\"550\" y=\"115\" font-size=\"24\" fill=\"#9ca3af\" text-anchor=\"middle\">Mentor, second father, fellow Declaration signer</text><rect x=\"100\" y=\"180\" width=\"900\" height=\"110\" fill=\"#6366f1\" opacity=\"0.2\" stroke=\"#6366f1\" stroke-width=\"2\" rx=\"10\"/><text x=\"550\" y=\"225\" font-size=\"26\" fill=\"#6366f1\" text-anchor=\"middle\" font-weight=\"bold\">Five-Year Apprenticeship 1762-1767</text><text x=\"550\" y=\"265\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Coke on Littleton and English common law</text><rect x=\"100\" y=\"320\" width=\"900\" height=\"110\" fill=\"#8b5cf6\" opacity=\"0.2\" stroke=\"#8b5cf6\" stroke-width=\"2\" rx=\"10\"/><text x=\"550\" y=\"365\" font-size=\"26\" fill=\"#8b5cf6\" text-anchor=\"middle\" font-weight=\"bold\">Classical Polymath</text><text x=\"550\" y=\"405\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Self-taught Greek, taught Jefferson Tacitus</text><rect x=\"100\" y=\"460\" width=\"900\" height=\"110\" fill=\"#10b981\" opacity=\"0.2\" stroke=\"#10b981\" stroke-width=\"2\" rx=\"10\"/><text x=\"550\" y=\"505\" font-size=\"26\" fill=\"#10b981\" text-anchor=\"middle\" font-weight=\"bold\">First U.S. Law Professor</text><text x=\"550\" y=\"545\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">William and Mary chair endowed 1779</text><rect x=\"100\" y=\"600\" width=\"900\" height=\"110\" fill=\"#f59e0b\" opacity=\"0.2\" stroke=\"#f59e0b\" stroke-width=\"2\" rx=\"10\"/><text x=\"550\" y=\"645\" font-size=\"26\" fill=\"#f59e0b\" text-anchor=\"middle\" font-weight=\"bold\">Signed the Declaration</text><text x=\"550\" y=\"685\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">First Virginia signer, pupil drafted text</text><rect x=\"100\" y=\"740\" width=\"900\" height=\"110\" fill=\"#ef4444\" opacity=\"0.2\" stroke=\"#ef4444\" stroke-width=\"2\" rx=\"10\"/><text x=\"550\" y=\"785\" font-size=\"26\" fill=\"#ef4444\" text-anchor=\"middle\" font-weight=\"bold\">Freed His Enslaved People</text><text x=\"550\" y=\"825\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Manumitted in life, then provided for in will</text><rect x=\"100\" y=\"880\" width=\"900\" height=\"110\" fill=\"#ec4899\" opacity=\"0.2\" stroke=\"#ec4899\" stroke-width=\"2\" rx=\"10\"/><text x=\"550\" y=\"925\" font-size=\"26\" fill=\"#ec4899\" text-anchor=\"middle\" font-weight=\"bold\">Poisoned by Grandnephew 1806</text><text x=\"550\" y=\"965\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Arsenic in coffee, died after testifying</text><text x=\"550\" y=\"1040\" font-size=\"18\" fill=\"#9ca3af\" text-anchor=\"middle\">A mentor who lived the egalitarian ideals Jefferson preached</text></svg>",
